//! DDS type support for the Rust code generated by `rustorb-idl -brust
//! -Wbdds`.
//!
//! - [`TypeSupport`] is implemented by every IDL type the generated code
//!   uses: the primitive Rust types, the descriptors of this crate for the
//!   IDL types that share a Rust type ([`Char8`], [`Char16`], [`Str`],
//!   [`WStr`], [`BoundedStr`], [`BoundedWStr`], [`Seq`], [`BoundedSeq`],
//!   [`Array`], [`External`]) and the generated structs, unions, enums and
//!   bitmasks. It writes and reads a value in Extended CDR (DDS-XTypes 1.3
//!   clause 7.4), version 1 or 2 by the encoding of the
//!   [`Encoder`]/[`Decoder`], and writes the key holder of the value
//!   (DDS-XTypes 7.6.8).
//! - [`TopicType`] is implemented by the generated structs and unions that
//!   are not `@nested`: the type name, the RTPS SerializedPayload
//!   ([`to_payload`](TopicType::to_payload),
//!   [`from_payload`](TopicType::from_payload)) and the key hash
//!   ([`key_hash`](TopicType::key_hash)).
//! - The functions of [`aggregate`] are what generated structs and unions
//!   call to write their headers: the DHEADER of appendable and mutable
//!   types, member headers and parameter lists, and optional members.
//!
//! The crate depends on `rustorb-cdr` only, so code generated for DDS
//! does not depend on the ORB.

mod aggregate_impl;
mod error;
mod md5;
mod types;

pub use error::{Error, Result};
pub use md5::md5;
pub use rustorb_cdr::xcdr::{Extensibility, XcdrFormat};
pub use rustorb_cdr::{ByteOrder, Decoder, Encoder, Encoding, LongDouble};
pub use types::{
    Array, BoundedSeq, BoundedStr, BoundedWStr, Char8, Char16, External, Seq, Str, WStr,
};

/// What generated code calls to write and read aggregated types.
pub mod aggregate {
    pub use crate::aggregate_impl::*;
}

/// Checked by generated code: code written for another version of this
/// crate does not compile.
pub const GENERATED_CODE_VERSION_1: () = ();

/// An IDL type, as DDS-XTypes Extended CDR writes it.
///
/// `Rust` is the Rust type of its values: `Self` for the primitive types
/// and the generated types, another type for the descriptors of this crate
/// (`Str::Rust` is `String`).
///
/// [`write`](TypeSupport::write) and [`read`](TypeSupport::read) follow
/// the encoding version of the stream: [`Encoding::Xcdr2`] for XCDR2, any
/// other for XCDR1.
pub trait TypeSupport {
    /// The Rust type of the values.
    type Rust;

    /// Whether this is a primitive type of DDS-XTypes 7.2.2.2 (boolean,
    /// byte, the integers, the floating point types and the characters).
    /// In XCDR2 a sequence or array of anything else has a DHEADER (rules
    /// 9 and 12 of 7.4.3.5.3).
    const PRIMITIVE: bool = false;

    /// The element type of an array, arrays of arrays being one array
    /// (DDS-XTypes Table 40, ARRAY_TYPE), is primitive. Only [`Array`]
    /// overrides this.
    #[doc(hidden)]
    const ARRAY_ELEMENT_PRIMITIVE: bool = Self::PRIMITIVE;

    /// Writes `v`.
    fn write(v: &Self::Rust, enc: &mut Encoder) -> Result<()>;

    /// Reads a value.
    fn read(dec: &mut Decoder<'_>) -> Result<Self::Rust>;

    /// Writes `v` as its key holder (DDS-XTypes 7.6.8, steps 1 to 3): for
    /// an aggregated type, as a final type with its key members (all its
    /// members when it has none) in the order of their member IDs, each
    /// written as its own key holder. The elements of sequences and arrays
    /// are written as key holders too. The stream is PLAIN_CDR2.
    fn write_key(v: &Self::Rust, enc: &mut Encoder) -> Result<()> {
        Self::write(v, enc)
    }

    /// The offset after the largest key holder written at `offset` in
    /// PLAIN_CDR2, or `None` when it has no bound. This decides whether a
    /// key hash is the key holder itself or its MD5 (DDS-XTypes 7.6.8,
    /// step 5).
    fn max_key_end(offset: usize) -> Option<usize>;

    /// Writes the elements of a slice, without a length. Overridden for
    /// `u8` to copy the bytes in one go.
    #[doc(hidden)]
    fn write_slice(items: &[Self::Rust], enc: &mut Encoder) -> Result<()> {
        items.iter().try_for_each(|item| Self::write(item, enc))
    }

    /// Reads `len` elements. Overridden for `u8` to copy the bytes in one
    /// go.
    #[doc(hidden)]
    fn read_vec(len: usize, dec: &mut Decoder<'_>) -> Result<Vec<Self::Rust>> {
        let mut items = Vec::with_capacity(len.min(4096));
        for _ in 0..len {
            items.push(Self::read(dec)?);
        }
        Ok(items)
    }

    /// Writes the elements of a slice as key holders, without a length.
    #[doc(hidden)]
    fn write_key_slice(items: &[Self::Rust], enc: &mut Encoder) -> Result<()> {
        items.iter().try_for_each(|item| Self::write_key(item, enc))
    }

    /// Writes `v` (as its key holder when `key`) as an element of an
    /// enclosing array: an array inside an array has no DHEADER of its
    /// own.
    #[doc(hidden)]
    fn write_in_array(v: &Self::Rust, enc: &mut Encoder, key: bool) -> Result<()> {
        if key {
            Self::write_key(v, enc)
        } else {
            Self::write(v, enc)
        }
    }

    /// Reads an element of an enclosing array; see
    /// [`write_in_array`](TypeSupport::write_in_array).
    #[doc(hidden)]
    fn read_in_array(dec: &mut Decoder<'_>) -> Result<Self::Rust> {
        Self::read(dec)
    }

    /// The offset after the largest element of an enclosing array written
    /// at `offset`; see [`write_in_array`](TypeSupport::write_in_array).
    #[doc(hidden)]
    fn max_key_end_in_array(offset: usize) -> Option<usize> {
        Self::max_key_end(offset)
    }
}

/// The key hash of an instance (DDS-XTypes 7.6.8, DDSI-RTPS 9.6.4.8).
pub type KeyHash = [u8; 16];

/// A type a DDS DataWriter publishes: a generated struct or union that is
/// not `@nested` (DDS-XTypes 7.3.1.2.1.7 and 7.3.1.2.1.16).
pub trait TopicType: TypeSupport<Rust = Self> + Sized {
    /// The fully qualified name of the type (`"Module::Type"`).
    const TYPE_NAME: &'static str;

    /// The extensibility kind (`@final`, `@appendable`, `@mutable`).
    const EXTENSIBILITY: Extensibility;

    /// Whether the type has key members.
    const KEYED: bool;

    /// The RTPS SerializedPayload of `self`: the encapsulation header of
    /// `encoding` (which must be [`Encoding::Xcdr1`] or
    /// [`Encoding::Xcdr2`]) and the extensibility of the type, the value,
    /// and the padding to 4 octets (DDS-XTypes 7.4.3.5.3 rule 1,
    /// DDSI-RTPS 10).
    fn to_payload(&self, encoding: Encoding, order: ByteOrder) -> Result<Vec<u8>> {
        let format = XcdrFormat::new(encoding, Self::EXTENSIBILITY).ok_or(Error::NotXcdr)?;
        let mut enc = Encoder::xcdr_payload(format, order);
        Self::write(self, &mut enc)?;
        Ok(enc.finish_xcdr_payload())
    }

    /// Reads a value from an RTPS SerializedPayload. Its format must be
    /// the one of the extensibility of the type: PL_CDR or PL_CDR2 for a
    /// mutable type, PLAIN_CDR or DELIMITED_CDR for an appendable one,
    /// PLAIN_CDR or PLAIN_CDR2 for a final one.
    fn from_payload(buf: &[u8]) -> Result<Self> {
        let (mut dec, header) = Decoder::xcdr_payload(buf)?;
        let format = header.id.format;
        if XcdrFormat::new(format.encoding(), Self::EXTENSIBILITY) != Some(format) {
            return Err(Error::FormatMismatch(format));
        }
        Self::read(&mut dec)
    }

    /// The PLAIN_CDR2 big endian serialization of the key holder of
    /// `self` (DDS-XTypes 7.6.8, step 4).
    fn key_holder(&self) -> Result<Vec<u8>> {
        let mut enc = Encoder::new(ByteOrder::Big, Encoding::Xcdr2);
        Self::write_key(self, &mut enc)?;
        Ok(enc.into_bytes())
    }

    /// The key hash of `self` (DDS-XTypes 7.6.8, step 5): the key holder
    /// padded with zeros when the largest one fits in 16 octets, its MD5
    /// otherwise.
    fn key_hash(&self) -> Result<KeyHash> {
        let holder = self.key_holder()?;
        match Self::max_key_end(0) {
            Some(max) if max <= 16 => {
                let mut hash = [0u8; 16];
                hash[..holder.len()].copy_from_slice(&holder);
                Ok(hash)
            }
            _ => Ok(md5(&holder)),
        }
    }
}

/// The member ID of DDS-XTypes 7.3.1.2.1.1 computed from a string (a
/// member name, or the parameter of `@hashid`): the first 4 octets of its
/// MD5 as a little endian integer, with the top 4 bits cleared.
pub fn hashed_member_id(name: &str) -> u32 {
    let d = md5(name.as_bytes());
    u32::from_le_bytes([d[0], d[1], d[2], d[3]]) & 0x0FFF_FFFF
}

/// `offset` rounded up to a multiple of `align`, as PLAIN_CDR2 aligns (to
/// no more than 4).
pub fn align_up(offset: usize, align: usize) -> usize {
    let align = align.clamp(1, 4);
    offset.div_ceil(align) * align
}

#[cfg(test)]
mod tests {
    use super::hashed_member_id;

    /// The example of DDS-XTypes 7.3.1.2.1.1.
    #[test]
    fn member_id_hash() {
        assert_eq!(hashed_member_id("color"), 0x0FA5DD70);
        assert_eq!(hashed_member_id("shapesize"), 0x047790DA);
    }
}
